<script setup lang="ts">
import type { FormError, FormSubmitEvent } from '@nuxt/ui'
import type { VocabSet, VocabSetPayload } from '~/types/vocab'
import type { Image } from '~/utils/imgManagement'
// Imported explicitly: it is opened from script code, where auto-imported components are unavailable
import ImageManager from '~/components/admin/ImageManager.vue'

// Create/edit form for a vocabulary set, shown in a content dialog. Emits "close" with true after saving.
// The slug is generated by the backend from the name, so it is not editable here.
// When "userId" is given the form runs in user mode: it saves through the user API (POST /vocab/set) with the
// owner id and hides the banner picker (the image manager is admin-only). Without it, it behaves as before.
const props = defineProps<{ set?: VocabSet, userId?: number }>()
const emit = defineEmits<{ close: [saved?: boolean] }>()

const adminApi = useVocabAdminApi()
const userApi = useVocabApi()
const isUserMode = computed(() => props.userId !== undefined)
const dialogStore = useDialogStore()

const state = reactive<VocabSetPayload>({
  id: props.set?.id,
  name: props.set?.name ?? '',
  description: props.set?.description ?? '',
  imgBanner: props.set?.imgBanner ?? null
})
const loading = ref(false)

// Open the image manager on top of this form and store the chosen path
async function pickBanner() {
  const image = await dialogStore.content<Image>({
    title: 'Chọn ảnh banner',
    component: ImageManager,
    props: { selected: state.imgBanner },
    widthClass: 'sm:max-w-4xl'
  })
  if (image) state.imgBanner = image.src
}

function validate(values: Partial<VocabSetPayload>): FormError[] {
  return values.name?.trim() ? [] : [{ name: 'name', message: 'Vui lòng nhập tên' }]
}

// Errors are displayed by the global API error dialog; we only stop the spinner
async function onSubmit(event: FormSubmitEvent<VocabSetPayload>) {
  loading.value = true
  try {
    if (isUserMode.value) await userApi.saveSet({ ...event.data, id: props.set?.id, userId: props.userId })
    else await adminApi.saveSet({ ...event.data, id: props.set?.id })
    emit('close', true)
  } catch (e) {
    if (!(e instanceof ApiError)) throw e
  } finally {
    loading.value = false
  }
}
</script>

<template>
  <UForm :state="state" :validate="validate" class="space-y-4" @submit="onSubmit">
    <UFormField label="Tên bộ từ vựng" name="name" required>
      <UInput v-model="state.name" class="w-full" autofocus placeholder="VD: Từ vựng IELTS cơ bản" />
    </UFormField>

    <UFormField label="Mô tả" name="description">
      <UTextarea v-model="state.description" class="w-full" :rows="4" placeholder="Mô tả ngắn (không bắt buộc)" />
    </UFormField>

    <UFormField v-if="!isUserMode" label="Ảnh banner" name="imgBanner">
      <div class="flex items-center gap-3">
        <img
          v-if="state.imgBanner"
          :src="imgUrl(state.imgBanner)"
          alt="Ảnh banner"
          class="aspect-video w-40 rounded-lg border border-default object-cover"
        >
        <div v-else class="flex aspect-video w-40 items-center justify-center rounded-lg border border-dashed border-default text-dimmed">
          <UIcon name="i-lucide-image" class="size-6" />
        </div>
        <div class="flex flex-col gap-2">
          <UButton color="neutral" variant="outline" icon="i-lucide-images" class="transition duration-200 active:scale-95" @click="pickBanner">
            {{ state.imgBanner ? 'Đổi ảnh' : 'Chọn ảnh' }}
          </UButton>
          <UButton v-if="state.imgBanner" color="error" variant="ghost" icon="i-lucide-x" class="transition duration-200 active:scale-95" @click="state.imgBanner = null">
            Bỏ ảnh
          </UButton>
        </div>
      </div>
    </UFormField>

    <!-- Right-aligned actions -->
    <div class="flex justify-end gap-2 pt-2">
      <UButton color="neutral" variant="outline" class="transition duration-200 active:scale-95" @click="emit('close')">
        Hủy
      </UButton>
      <UButton type="submit" :loading="loading" class="transition duration-200 active:scale-95">
        {{ set ? 'Lưu thay đổi' : 'Tạo bộ từ vựng' }}
      </UButton>
    </div>
  </UForm>
</template>
